#define M_PI 3.1415926535897932384626433832795

// CONFIGS

const float angle = 42.0;
const float growth = 1.0 / 30.0;
const float count = 500.0;
const vec2 spinCenter = vec2(0.5, 0.5);

vec2 circleCenter( in float i )
{
    return vec2(0.4 * i / count, 0.4 * i / count);
}

float iterationBias ( in float i )
{
    return (2.0 * count - i) / count;
}

float circleRadius( in float i )
{
    return 0.04 * i / count;
}

vec3 colorer( in float i )
{
    return vec3(fract(i * 5.0 / count), i / count, (count - i) / count);
}

// UTILS

float degToRad(in float angle ) {
    return M_PI * angle / 180.0;
}

vec2 spinUVs( in vec2 center, in vec2 uv, in float iteration )
{
    vec2 localized = uv - center;
    float mag = length(localized);
    localized = localized / mag;

    float theta = degToRad(iteration * angle);

    float cs = cos(theta);
    float sn = sin(theta);

    localized = vec2(localized.x * cs - localized.y * sn, localized.x * sn + localized.y * cs);

    localized *= fract((mag + (growth * iteration)));

    return localized + center;
}

vec3 sampleSquare( in vec2 topLeft, in vec2 size, in vec2 uv ) {
    return vec3( 
        step(topLeft.x, uv.x) *
        step(uv.x, topLeft.x + size.x) *
        step(topLeft.y, uv.y) *
        step(uv.y, topLeft.y + size.y)
    );
}

vec3 sampleCircle( in vec2 center, in float radius, in vec2 uv ) {
    return vec3(
        step(length(uv - center), radius)
    );
}

// ACTUAL CODE

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    // Comment for "skewed" version
    vec2 res = iResolution.xy/iResolution.y;
    vec3 col = vec3(0.0, 0.0, 0.0);

    for(float i = 0.0; i < count; i += 1.0) {
        // Normal version
        vec2 spun = spinUVs(spinCenter*res, uv, i + iTime * iterationBias(i));
        vec3 localCol = sampleCircle(circleCenter(i)*res, circleRadius(i), spun);

        // Original "skewed" 
        // vec2 spun = spinUVs(spinCenter, uv, i + iTime);
        // vec3 localCol = sampleCircle(circleCenter(i), circleRadius(i), spun);
        col += localCol * colorer(i);
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
